const EMA = "U09Q26PVD0T";
const b = (($input.first().json || {}).body) || {};
const kind = String(b.kind || '');
const n = v => { const x = Number(v); return Number.isFinite(x) ? x : 0; };
const plural = (c, one, many) => c + ' ' + (c === 1 ? one : (many || one + 's'));

// ⚠️ `sample: true` labels the post as a demonstration. A message that reads
// exactly like a real daily report but is not one would be misleading in a shared
// channel: and the numbers below would look like a day that never happened.
const stamp = out => (b.sample
  ? ':test_tube: _SAMPLE — nothing actually ran, this is what the real message looks like_\n\n' + out
  : out);

// 1: the collector finished its last scheduled batch of the day
if (kind === 'links_collected') {
  const links = n(b.links), companies = n(b.companies), boards = n(b.boards_with_links);
  const lines = [
    ':inbox_tray: *Link collection finished for today* (batch 4 of 4)',
    '',
    '*New job links collected:* ' + links,
    '*Companies read:* ' + companies + (boards ? '  (' + boards + ' had at least one link)' : ''),
  ];
  if (n(b.batches) && n(b.batches) < 4) {
    lines.push('', ':warning: only ' + n(b.batches) + ' of the 4 batches reported in today — one may have failed part-way.');
  }
  lines.push('', '_Next: the sheet cleanup runs at 12:00 and will tell you when it is ready for the Final Check._');
  return [{ json: { text: stamp(lines.join('\n')) } }];
}

// 2: the daily cleanup finished: duplicates removed, today's rows moved over
if (kind === 'cleanup_done') {
  const deleted = n(b.deleted), yellow = n(b.yellow), green = n(b.green);
  const copied = n(b.copied), waiting = n(b.waiting), older = n(b.older);
  const lines = [
    ':broom: *Sheet cleanup done — ready for the Final Check*',
    '',
    '*Duplicates deleted from Database:* ' + deleted +
      (deleted ? '  (' + yellow + ' already resolved before, ' + green + ' repeated today)' : ''),
    '*Rows transferred to Main Filter:* ' + copied,
    '*Waiting to be checked:* ' + waiting
  ];
  if (older) lines.push('', ':warning: ' + plural(older, 'older blank row') + ' still sitting on Database from a previous day.');
  lines.push('', waiting
    ? '<@' + EMA + '> ready for final checking — type *Final Check* here and I will start it.'
    : 'Nothing is waiting, so there is no need to run the Final Check today.');
  return [{ json: { text: stamp(lines.join('\n')) } }];
}

// 3: the cleanup deliberately did nothing and needs a human
if (kind === 'cleanup_blocked') {
  return [{ json: { text: stamp([
    ':warning: *Sheet cleanup did not run* — nothing was changed.',
    '',
    String(b.reason || 'no reason given').slice(0, 400),
    '',
    '_It will try again by itself at 13:00._'
  ].join('\n')) } }];
}

// 4: the Final Check finished (started by chatting "Final Check" in this channel)
if (kind === 'check_done') {
  const checked = n(b.checked), transferred = n(b.transferred), duplicate = n(b.duplicate);
  const noSalary = n(b.no_salary), errors = n(b.errors), planned = n(b.planned), tab = String(b.tab || 'Main Filter');
  const lines = [
    ':white_check_mark: *Final Check done* — ' + tab,
    '',
    '*Rows checked:* ' + checked,
    '*New — sent to Airtable:* ' + transferred,
    '*Duplicates:* ' + duplicate
  ];
  if (noSalary) lines.push('*No salary:* ' + noSalary);
  if (errors) lines.push('*Errors — need a manual check:* ' + errors);
  // A row whose Airtable push failed keeps a BLANK status on purpose, so the next run retries it.
  const left = planned - checked;
  if (left > 0) {
    lines.push('', ':warning: ' + plural(left, 'row') + ' still blank — the Airtable push failed for those. ' +
      'Run *Final Check* again and they will be retried.');
  }
  if (errors) {
    lines.push('', ':warning: ' + plural(errors, 'row') + ' marked *Error - Manual Check* — the Bandana lookup failed for them.');
  }
  return [{ json: { text: stamp(lines.join('\n')) } }];
}

return [];
